module structured_nested_bytes
fn payload_size(values: NestedValues<Vec<u8>, 2, 8, 64>) -> u64 { return values[0].len() }
action verify(witness values: NestedValues<Vec<u8>, 2, 8, 64>) -> u64 { verification require payload_size(values) == 2 return 0 }

module structured_nested_records
struct Entry { key: u64, payload: Vec<u8> }
fn key(entry: NestedRecordView<Entry, 8>) -> u64 { return entry.key }
fn inspect(values: NestedValues<Entry, 2, 8, 128>) -> bool { let entry = values[0] return key(entry) == 42 && entry.payload[0] == 7 }
action verify(witness values: NestedValues<Entry, 2, 8, 128>) -> u64 { verification require inspect(values) return 0 }
